<?php
namespace App\Http\Controllers\Admin;use App\Domain\Industries\{IndustryDependencyInspector,IndustryManager,IndustryRegistry,IndustryRelationManager,IndustryViewData};use App\Domain\Installation\WebsiteSettings;use App\Http\Controllers\{Controller,PublicSiteController};use App\Http\Requests\Industries\SaveIndustryRequest;use App\Models\{Industry,IndustryCategory,Page,Product,Solution};use Illuminate\Contracts\View\View;use Illuminate\Http\{RedirectResponse,Request,Response};use Illuminate\Support\Carbon;use Illuminate\Support\Str;use Illuminate\Validation\Rule;class IndustryController extends Controller{public function index(Request $r):View{$f=$r->validate(['search'=>['nullable','string','max:160'],'category'=>['nullable','integer'],'status'=>['nullable',Rule::in(['draft','published','scheduled','archived'])],'featured'=>['nullable','in:0,1'],'archived'=>['nullable','in:with,only,without'],'template'=>['nullable',Rule::in(IndustryRegistry::TEMPLATES)],'sort'=>['nullable','in:title,updated_at,published_at,display_order'],'direction'=>['nullable','in:asc,desc']]);$q=Industry::with('category')->withCount(['relatedSolutions','relatedProducts'])->when($f['search']??null,fn($q,$v)=>$q->where(fn($q)=>$q->where('title','like',"%$v%")->orWhere('slug','like',"%$v%")))->when($f['category']??null,fn($q,$v)=>$q->where('industry_category_id',$v))->when($f['status']??null,fn($q,$v)=>$q->where('status',$v))->when($f['template']??null,fn($q,$v)=>$q->where('template',$v))->when(isset($f['featured']),fn($q)=>$q->where('is_featured',(bool)$f['featured']));if(($f['archived']??'without')==='only'){$q->whereNotNull('archived_at');}elseif(($f['archived']??'without')==='without'){$q->whereNull('archived_at');}return view('admin.industries.index',['industries'=>$q->orderBy($f['sort']??'display_order',$f['direction']??'asc')->paginate(20)->withQueryString(),'f'=>$f,'categories'=>IndustryCategory::orderBy('display_order')->get(),'templates'=>IndustryRegistry::TEMPLATES]);}public function create():View{return $this->editor(new Industry);}public function store(SaveIndustryRequest $r,IndustryManager $manager):RedirectResponse{$industry=$manager->save($r->validated(),null,$r->user()->id);return redirect()->route('admin.industries.edit',$industry)->with('status','Draft industry created.');}public function edit(Industry $industry):View{return $this->editor($industry);}public function update(SaveIndustryRequest $r,Industry $industry,IndustryManager $manager):RedirectResponse{$manager->save($r->validated(),$industry,$r->user()->id);return back()->with('status','Industry saved without changing publication state.');}private function editor(Industry $industry):View{if($industry->exists){$industry->load(['challenges','outcomes','needs','useCases','relatedSolutions','relatedProducts','relatedPages']);}return view('admin.industries.editor',['industry'=>$industry,'categories'=>IndustryCategory::where('is_active',true)->orderBy('display_order')->get(),'templates'=>IndustryRegistry::TEMPLATES,'heroes'=>IndustryRegistry::HERO_STYLES,'icons'=>IndustryRegistry::ICONS,'solutions'=>Solution::whereNull('archived_at')->orderBy('title')->limit(200)->get(),'products'=>Product::whereNull('archived_at')->orderBy('title')->limit(200)->get(),'pages'=>Page::whereNull('archived_at')->orderBy('title')->limit(200)->get(),'dependencies'=>$industry->exists?app(IndustryDependencyInspector::class)->inspect($industry):null]);}public function publish(Industry $industry,IndustryManager $manager):RedirectResponse{$manager->publish($industry);return back()->with('status','Industry published.');}public function schedule(Request $r,Industry $industry,IndustryManager $manager):RedirectResponse{$value=$r->validate(['scheduled_for'=>['required','date']]);$timezone=app(WebsiteSettings::class)->current()?->timezone?:'UTC';$manager->schedule($industry,Carbon::parse($value['scheduled_for'],$timezone)->utc()->toDateTimeString());return back()->with('status','Industry scheduled.');}public function unpublish(Industry $industry,IndustryManager $manager):RedirectResponse{$manager->unpublish($industry);return back()->with('status','Industry returned to draft.');}public function archive(Industry $industry,IndustryManager $manager):RedirectResponse{$manager->archive($industry);return back()->with('status','Industry archived.');}public function restore(Industry $industry,IndustryManager $manager):RedirectResponse{$manager->restore($industry);return back()->with('status','Industry restored to draft.');}public function duplicate(Request $r,Industry $industry,IndustryManager $manager):RedirectResponse{$copy=$manager->duplicate($industry,$r->user()->id);return redirect()->route('admin.industries.edit',$copy)->with('status','Draft duplicate created.');}public function move(Industry $industry,string $direction,IndustryManager $manager):RedirectResponse{$manager->move($industry,$direction);return back();}public function relations(Request $r,Industry $industry,IndustryRelationManager $manager):RedirectResponse{$data=$r->validate(['related_solution_ids'=>['array','max:8'],'related_solution_ids.*'=>['integer','distinct','exists:solutions,id'],'related_product_ids'=>['array','max:8'],'related_product_ids.*'=>['integer','distinct','exists:products,id'],'related_page_ids'=>['array','max:6'],'related_page_ids.*'=>['integer','distinct','exists:pages,id']]);$manager->sync($industry,$data['related_solution_ids']??[],$data['related_product_ids']??[],$data['related_page_ids']??[]);return back()->with('status','Relations saved.');}public function preview(Request $r,Industry $industry,IndustryViewData $data):Response{return response()->view('industries.show',['industry'=>$data->preview($industry),'preview'=>true]+app(PublicSiteController::class)->sharedViewData($r))->header('Cache-Control','no-store, private, max-age=0')->header('X-Robots-Tag','noindex, nofollow');}public function categories():View{return view('admin.industries.categories',['categories'=>IndustryCategory::withCount('industries')->orderBy('display_order')->get()]);}public function storeCategory(Request $r,IndustryManager $manager):RedirectResponse{$manager->saveCategory($this->categoryData($r));return back()->with('status','Category created.');}public function updateCategory(Request $r,IndustryCategory $category,IndustryManager $manager):RedirectResponse{$manager->saveCategory($this->categoryData($r,$category),$category);return back()->with('status','Category updated.');}public function moveCategory(IndustryCategory $category,string $direction,IndustryManager $manager):RedirectResponse{$manager->moveCategory($category,$direction);return back();}private function categoryData(Request $r,?IndustryCategory $category=null):array{$raw=(string)$r->input('slug');$r->merge(['slug'=>(str_contains($raw,'/')||str_contains($raw,'\\')||str_contains($raw,'..'))?'':Str::slug(Str::lower($raw)),'is_active'=>$r->boolean('is_active')]);return $r->validate(['name'=>['required','string','max:120'],'slug'=>['required','regex:/^[a-z0-9]+(?:-[a-z0-9]+)*$/',Rule::unique('industry_categories')->ignore($category)],'description'=>['nullable','string','max:2000'],'is_active'=>['boolean']]);}}
